<script setup>
import {computed, reactive} from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});
function parse(value){try{return JSON.parse(value||'{}')}catch{return {}}}
const payload=parse(props.payload), errors=parse(props.errors), old=parse(props.old), payment=payload.payment||{};
const form=reactive({order_id:old.order_id??payment.order_id??'',amount:old.amount??payment.amount??'',payment_method:old.payment_method??payment.payment_method??'cash_on_delivery',payment_status:old.payment_status??payment.payment_status??'pending',paid_at:old.paid_at??payment.paid_at??'',note:old.note??payment.note??''});
const action=computed(()=>props.mode==='create'?props.storeUrl:props.updateUrl);
const methods=['cash_on_delivery','credit_card','debit_card','paypal'], statuses=['pending','paid','failed','refunded'];
</script>
<template>
<div class="orders-edit-page" v-if="mode==='create'||mode==='edit'">
<header class="orders-edit-header"><div class="orders-edit-heading"><div class="orders-edit-eyebrow"><i class="bi bi-credit-card-2-front"></i> Payment Management</div><h1>{{mode==='create'?'Create Payment':'Edit Payment'}}</h1><p>{{mode==='create'?'Create a new customer payment manually.':'Update transaction, order, payment and status information.'}}</p></div><a :href="indexUrl" class="orders-edit-back"><i class="bi bi-arrow-left"></i><span>Back to Payments</span></a></header>
<div class="orders-edit-card"><div class="orders-edit-card-header"><div class="orders-edit-card-icon"><i class="bi bi-credit-card"></i></div><div class="orders-edit-card-title"><strong>{{mode==='create'?'New Payment':'Payment #'+payment.id}}</strong><span>Fill in the information associated with this payment.</span></div></div><div class="orders-edit-card-body">
<div v-if="Object.keys(errors).length" class="orders-edit-errors"><div class="orders-edit-errors-title"><i class="bi bi-exclamation-triangle"></i> Please fix the following errors:</div><ul><li v-for="(messages,key) in errors" :key="key">{{messages[0]}}</li></ul></div>
<form :action="action" method="POST"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT">
<div class="orders-edit-section"><div class="orders-edit-section-heading"><i class="bi bi-receipt"></i><span>{{mode==='create'?'Order & Amount':'Transaction & Order'}}</span></div><div class="orders-edit-grid"><div v-if="mode==='edit'" class="orders-edit-field span-6"><label class="orders-edit-label">Transaction ID</label><input class="orders-edit-input" :value="payment.transaction_id" disabled></div><div class="orders-edit-field span-6"><label class="orders-edit-label" for="order_id">Order <span class="required">*</span></label><select id="order_id" v-model="form.order_id" name="order_id" class="orders-edit-select" required><option value="">Select Order</option><option v-for="order in payload.orders||[]" :key="order.id" :value="order.id">{{order.order_number}} - {{order.customer}} - ${{Number(order.total_price).toFixed(2)}}</option></select><div v-if="errors.order_id" class="orders-edit-field-error">{{errors.order_id[0]}}</div></div><div class="orders-edit-field span-6"><label class="orders-edit-label" for="amount">Amount <span class="required">*</span></label><input id="amount" v-model="form.amount" name="amount" type="number" step="0.01" min="0" class="orders-edit-input" required><div v-if="errors.amount" class="orders-edit-field-error">{{errors.amount[0]}}</div></div></div></div>
<div class="orders-edit-section"><div class="orders-edit-section-heading"><i class="bi bi-wallet2"></i><span>Payment Information</span></div><div class="orders-edit-grid"><div class="orders-edit-field span-6"><label class="orders-edit-label">Payment Method <span class="required">*</span></label><select v-model="form.payment_method" name="payment_method" class="orders-edit-select" required><option v-for="method in methods" :key="method" :value="method">{{method.replaceAll('_',' ')}}</option></select></div><div class="orders-edit-field span-6"><label class="orders-edit-label">Payment Status <span class="required">*</span></label><select v-model="form.payment_status" name="payment_status" class="orders-edit-select" required><option v-for="status in statuses" :key="status">{{status}}</option></select></div><div class="orders-edit-field span-6"><label class="orders-edit-label">Paid At</label><input v-model="form.paid_at" type="datetime-local" name="paid_at" class="orders-edit-input"><div v-if="errors.paid_at" class="orders-edit-field-error">{{errors.paid_at[0]}}</div></div></div></div>
<div class="orders-edit-section"><div class="orders-edit-section-heading"><i class="bi bi-chat-left-text"></i><span>Payment Note</span></div><textarea v-model="form.note" name="note" rows="3" placeholder="Add an internal note about this payment..." class="orders-edit-textarea"></textarea></div>
<div class="orders-edit-footer"><a :href="indexUrl" class="orders-edit-cancel"><i class="bi bi-x-lg"></i> Cancel</a><button type="submit" class="orders-edit-submit"><i class="bi bi-check-circle"></i> {{mode==='create'?'Create Payment':'Save Payment'}}</button></div></form></div></div>
</div>
<div v-else class="orders-edit-page"><header class="orders-edit-header"><div class="orders-edit-heading"><h1>Payment #{{payment.id}}</h1><p>Transaction and associated order details.</p></div><a :href="payment.edit_url" class="orders-edit-back"><i class="bi bi-pencil"></i> Edit Payment</a></header><div class="orders-edit-card p-4"><dl class="row mb-0"><dt class="col-sm-4">Transaction ID</dt><dd class="col-sm-8">{{payment.transaction_id||'—'}}</dd><dt class="col-sm-4">Amount</dt><dd class="col-sm-8">${{Number(payment.amount).toFixed(2)}}</dd><dt class="col-sm-4">Payment status</dt><dd class="col-sm-8">{{payment.payment_status}}</dd><dt class="col-sm-4">Payment method</dt><dd class="col-sm-8">{{payment.payment_method?.replaceAll('_',' ')}}</dd><dt class="col-sm-4">Order</dt><dd class="col-sm-8">{{payment.order_number||'—'}} · {{payment.book||'—'}}</dd><dt class="col-sm-4">Customer</dt><dd class="col-sm-8">{{payment.customer||'—'}} · {{payment.email||'—'}}</dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8">{{payment.phone||'—'}}</dd><dt class="col-sm-4">Date</dt><dd class="col-sm-8">{{payment.created_at||'—'}}</dd></dl></div></div>
</template>
